        top, bottom = panels[source_panel]
        coords = {(r - top - 1, c - left_w - 1) for r, c in cells}
        objects.append((color, cells, source_panel, coords))

    def similarity(a, b):
        if not a or not b:
            return 0.0
        best = 0.0
        for dr in range(-len(a) - len(b), len(a) + len(b) + 1):
            for dc in range(-left_w, left_w + 1):
